// Erzeugt von medikamente/scripts/build-data.mjs – nicht von Hand bearbeiten (Quelle: data/src).
window.MEDI_DETAILS = Object.assign(window.MEDI_DETAILS || {}, {"cabergolin":{"wirkmechanismus":"Senkt die Menge des Hormons Prolaktin, das die Milchbildung anregt und bei Überschuss Zyklusstörungen, Unfruchtbarkeit und Libidoverlust verursacht. Cabergolin ist ein lang wirksamer Agonist an Dopamin-D2-Rezeptoren der prolaktinbildenden Zellen der Hirnanhangdrüse (Hypophyse) und hemmt dort die Prolaktinausschüttung; Prolaktinome können dabei schrumpfen. Wegen der sehr langen Halbwertszeit genügt meist eine Einnahme ein- bis zweimal pro Woche. Als Mutterkorn-(Ergolin-)Abkömmling stimuliert es auch Serotonin-5-HT2B-Rezeptoren, was mit Fibrosen und Herzklappenveränderungen in Verbindung gebracht wird.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Kopfschmerzen","Schwindel","Bauchschmerzen, Verdauungsbeschwerden (Dyspepsie), Magenschleimhautentzündung","Schwäche und Müdigkeit","Herzklappenveränderungen (Valvulopathie) und verwandte Störungen wie Herzbeutelentzündung oder -erguss"],"haeufig":["Depression","Schläfrigkeit (Somnolenz)","Verstopfung, Erbrechen","Blutdruckabfall beim Aufstehen (orthostatische Hypotonie)","Hitzewallungen","Brustschmerzen (Mastodynie)"],"gelegentlich":["Herzklopfen (Palpitationen)","Ohnmacht (Synkope), Kribbeln (Parästhesien)","Vorübergehende Gesichtsfeldausfälle","Atemnot, Pleuraerguss (Flüssigkeit im Brustfellraum), Lungenfibrose","Nasenbluten","Krämpfe der Fingergefässe (Vasospasmus)","Haarausfall, Hautausschlag","Wassereinlagerungen (Ödeme)","Wadenkrämpfe","Überempfindlichkeitsreaktionen, gesteigerte Libido"],"unbekannt":["Impulskontrollstörungen (Spielsucht, Kaufsucht, gesteigerter Sexualtrieb, Essattacken)","Plötzliches Einschlafen im Alltag","Halluzinationen, Wahnvorstellungen, psychotische Störungen, Aggression","Angina pectoris","Zittern (Tremor), Sehstörungen","Erhöhte Leberwerte und CK"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Bei Kinderwunsch Cabergolin vorsorglich etwa einen Monat vor der geplanten Empfängnis absetzen; tritt unter der Behandlung eine Schwangerschaft ein, ärztlich über das Absetzen entscheiden. Die bisherigen Erfahrungen zeigen kein erhöhtes Fehlbildungsrisiko.","stillzeit":"Cabergolin unterdrückt die Milchbildung. Frauen, die stillen möchten, dürfen es nicht einnehmen; bei Behandlung einer Hyperprolaktinämie nicht stillen.","hinweise":["Mit einer Mahlzeit einnehmen – das vermindert Übelkeit und Schwindel.","Bei Langzeitbehandlung vor Beginn und regelmässig einen Herzultraschall machen lassen; Atemnot, anhaltenden Husten, Brust- oder Flankenschmerzen und Beinödeme ärztlich abklären.","Kann Schläfrigkeit, plötzliches Einschlafen und Blutdruckabfall verursachen – Vorsicht beim Autofahren, besonders in den ersten Tagen.","Auf Spielsucht, Kaufsucht, gesteigerten Sexualtrieb oder Essattacken achten und Angehörige darüber informieren."],"darreichung":["Tabletten"]},"calcipotriol":{"wirkmechanismus":"Bremst das zu schnelle Wachstum der Hautzellen bei Schuppenflechte und normalisiert ihre Reifung. Calcipotriol ist ein synthetischer Abkömmling des aktiven Vitamin D3 (Calcitriol) und bindet an den Vitamin-D-Rezeptor der Hornzellen (Keratinozyten). Dadurch hemmt es deren Vermehrung, fördert eine normale Verhornung und dämpft entzündliche Signale. Seine Wirkung auf den Calciumhaushalt ist etwa 100-mal schwächer als die von Calcitriol; bei zu grossen Mengen kann der Calciumspiegel im Blut trotzdem steigen.","nebenwirkungen":{"haeufig":["Juckreiz","Hautreizung, Brennen, Stechen oder Schmerzen der Haut","Rötung, trockene Haut, Hautausschlag"],"gelegentlich":["Ekzem, Hautentzündung (Dermatitis)","Verschlechterung der Psoriasis"],"selten":["Hyperkalzämie (erhöhter Calciumspiegel im Blut) und vermehrte Calciumausscheidung im Urin"],"unbekannt":["Überempfindlichkeitsreaktionen wie Nesselsucht, Angioödem, Schwellung um die Augen oder im Gesicht","Lichtempfindlichkeit der Haut","Hautentzündung im Gesicht oder um den Mund (wenn Salbe dorthin gelangt)"]},"schwangerschaft":"Nur nach ärztlicher Abwägung: Erfahrungen beim Menschen fehlen; in Tierversuchen traten nach hohen Dosen zum Einnehmen schädliche Wirkungen auf.","stillzeit":"Nach ärztlicher Abwägung möglich; nicht im Brustbereich auftragen.","hinweise":["Höchstmenge beachten: Erwachsene höchstens 100 g Salbe pro Woche (bei Kombination mit Lösung entsprechend weniger); bei grossflächiger Anwendung kann der Arzt den Calciumspiegel kontrollieren.","Nach dem Auftragen Hände waschen; nicht ins Gesicht oder in die Augen bringen.","Übermässige Sonne und Solarium während der Behandlung meiden."],"darreichung":["Salbe","Lösung zur Anwendung auf der Kopfhaut"]},"calcipotriol-betamethason":{"wirkmechanismus":"Verbindet zwei Wirkprinzipien gegen Schuppenflechte. Calcipotriol, ein Abkömmling von Vitamin D3, bindet an den Vitamin-D-Rezeptor der Hornzellen, bremst deren übermässige Vermehrung und normalisiert die Verhornung. Betamethasondipropionat ist ein stark wirksames Glukokortikoid (Klasse III), das über den Glukokortikoid-Rezeptor Entzündung, Rötung und Juckreiz unterdrückt. Die Kombination wirkt schneller und stärker als jeder Wirkstoff allein, und das Kortison mildert die Hautreizung durch Calcipotriol.","nebenwirkungen":{"haeufig":["Juckreiz"],"gelegentlich":["Brennen, Reizung oder Schmerzen der Haut","Rötung, Ausschlag, Hautentzündung (Dermatitis)","Verschlechterung der Psoriasis","Hautinfektionen (Bakterien, Pilze, Viren), Haarbalgentzündung (Follikulitis)","Pigmentveränderungen an der Anwendungsstelle"],"selten":["Hautatrophie (Verdünnung der Haut), Dehnungsstreifen (Striae)","Pustulöse Psoriasis","Überempfindlichkeitsreaktionen, Nesselsucht","Rebound-Effekt (Wiederaufflammen nach dem Absetzen)","Hyperkalzämie (erhöhter Calciumspiegel im Blut)"],"unbekannt":["Verschwommenes Sehen","Vorübergehende gelbliche Verfärbung weisser oder grauer Haare (Gel auf der Kopfhaut)","Unterdrückung der Nebennierenrinde bei grossflächiger Anwendung"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung: Daten fehlen, und Kortison wirkte in Tierversuchen fruchtschädigend.","stillzeit":"Nach ärztlicher Abwägung möglich; nicht auf die Brust auftragen.","hinweise":["Höchstmengen beachten: höchstens 15 g pro Tag und 100 g pro Woche, nicht mehr als 30 % der Körperoberfläche.","Nach dem Auftragen Hände waschen; nicht ins Gesicht, in die Augen oder auf Schleimhäute bringen und nicht unter luftdichten Verbänden anwenden.","Der Schaum ist leicht entzündlich: beim Auftragen nicht rauchen und offene Flammen meiden."],"darreichung":["Salbe","Gel","Schaum zur Anwendung auf der Haut"]},"calcitriol":{"wirkmechanismus":"Ist die fertige, aktive Form von Vitamin D und muss – anders als gewöhnliches Vitamin D – nicht erst in Leber und Niere umgewandelt werden. Calcitriol (1,25-Dihydroxycholecalciferol) bindet an den Vitamin-D-Rezeptor und steigert dadurch die Aufnahme von Calcium und Phosphat aus dem Darm, die Rückresorption von Calcium in der Niere und die Mineralisierung des Knochens; zudem hemmt es die Bildung von Parathormon. Deshalb wirkt es auch, wenn die kranke Niere selbst kein aktives Vitamin D mehr bilden kann. Auf der Haut hemmt es die übermässige Vermehrung der Hornzellen (Keratinozyten) und fördert deren normale Ausreifung.","nebenwirkungen":{"sehrHaeufig":["Hyperkalzämie (erhöhtes Calcium im Blut) bei Einnahme der Kapseln"],"haeufig":["Kopfschmerzen","Bauchschmerzen, Übelkeit","Hautausschlag","Harnwegsinfekte","Salbe: Hautreizung, Rötung und Juckreiz an der behandelten Stelle"],"gelegentlich":["Appetitlosigkeit, Erbrechen","Anstieg des Kreatinins im Blut"],"unbekannt":["Zeichen einer Hyperkalzämie: Durst, vermehrtes Wasserlassen, Verstopfung, Muskelschwäche, Teilnahmslosigkeit","Kalkablagerungen in Geweben (Calcinose) und Nierensteine bei anhaltender Hyperkalzämie","Überempfindlichkeitsreaktionen (Juckreiz, Nesselsucht)","Wachstumsverzögerung bei Kindern mit anhaltender Hyperkalzämie"]},"schwangerschaft":"Nur bei klarer Notwendigkeit und unter Kontrolle des Calciums, da eine Hyperkalzämie der Mutter dem Kind schaden kann; die Salbe nur nach ärztlicher Abwägung und kleinflächig.","stillzeit":"Calcitriol geht in die Muttermilch über; Anwendung nur nach ärztlicher Abwägung mit Kontrolle des Calciums bei Mutter und Kind.","hinweise":["Blutkontrollen (Calcium, Phosphat, Kreatinin) zuverlässig wahrnehmen, besonders zu Beginn und nach Dosisänderungen.","Keine weiteren Vitamin-D- oder Calciumpräparate ohne ärztliche Absprache einnehmen; ausreichend trinken.","Warnzeichen zu hohen Calciums (starker Durst, viel Wasserlassen, Übelkeit, Verstopfung, Muskelschwäche, Verwirrtheit) ärztlich melden.","Salbe dünn auftragen und danach die Hände waschen."],"darreichung":["Weichkapseln","Salbe"]},"calcium":{"wirkmechanismus":"Ersetzt Calcium, das für Knochen und Zähne sowie für Muskeln, Nerven, Herz und Blutgerinnung unentbehrlich ist. Rund 99 % des Körpercalciums sind im Knochen gespeichert; eine ausreichende Zufuhr bremst den Knochenabbau, besonders zusammen mit Vitamin D, das die Aufnahme im Darm steigert. Calciumcarbonat braucht für die Aufnahme Magensäure und wird zu den Mahlzeiten besser aufgenommen, Calciumcitrat unabhängig davon. Intravenös gegebenes Calcium hebt einen gefährlich tiefen Calciumspiegel innert Minuten an.","nebenwirkungen":{"gelegentlich":["Hyperkalzämie (erhöhtes Calcium im Blut)","Hyperkalziurie (erhöhtes Calcium im Urin)"],"selten":["Verstopfung, Blähungen, Übelkeit, Bauchschmerzen, Durchfall"],"sehrSelten":["Juckreiz, Hautausschlag, Nesselsucht","Milch-Alkali-Syndrom (Hyperkalzämie, Alkalose, Nierenfunktionsstörung), meist nur bei Überdosierung"],"unbekannt":["Injektion: Wärmegefühl, Hitzewallung, Blutdruckabfall, langsamer Puls oder Rhythmusstörungen bei zu rascher Gabe","Injektion: Reizung oder Gewebeschäden an der Einstichstelle"]},"schwangerschaft":"In üblichen Dosen erlaubt, der Bedarf ist erhöht; hohe Dosen und eine Hyperkalzämie vermeiden.","stillzeit":"Erlaubt; Calcium geht in die Muttermilch über.","hinweise":["Calciumcarbonat am besten zu den Mahlzeiten einnehmen; Kautabletten kauen oder lutschen, Brausetabletten in Wasser auflösen.","Abstand zu Antibiotika (Tetracycline, Chinolone), Schilddrüsenhormonen, Bisphosphonaten und Eisen einhalten.","Lebensmittel mit viel Oxalsäure (Spinat, Rhabarber) oder Phytinsäure (Vollkorn) vermindern die Calciumaufnahme."],"darreichung":["Kautabletten","Brausetabletten","Lutschtabletten","Injektionslösung (Calciumgluconat)"]},"calcium-colecalciferol":{"wirkmechanismus":"Liefert gleichzeitig Calcium und Vitamin D3, die der Knochen für seine Festigkeit braucht. Vitamin D3 wird in Leber und Niere zu Calcitriol aktiviert und steigert die Aufnahme von Calcium im Darm; das Calcium wird in den Knochen eingebaut. Gemeinsam gleichen sie einen Mangel aus und senken das Parathormon, das bei Mangel den Knochenabbau antreibt (sekundärer Hyperparathyreoidismus). So wird der altersbedingte Knochenabbau gebremst.","nebenwirkungen":{"gelegentlich":["Hyperkalzämie (erhöhtes Calcium im Blut)","Hyperkalziurie (erhöhtes Calcium im Urin)"],"selten":["Verstopfung, Blähungen, Übelkeit, Bauchschmerzen, Durchfall"],"sehrSelten":["Juckreiz, Hautausschlag, Nesselsucht","Milch-Alkali-Syndrom (Hyperkalzämie, Alkalose, Nierenfunktionsstörung), meist nur bei Überdosierung"],"unbekannt":["Überempfindlichkeitsreaktionen wie Angioödem oder Kehlkopfschwellung"]},"schwangerschaft":"Bei Bedarf in üblichen Dosen erlaubt; in der Schwangerschaft insgesamt nicht mehr als 2500 mg Calcium und 4000 I. E. Vitamin D pro Tag aufnehmen.","stillzeit":"Erlaubt; Calcium und Vitamin D gehen in die Muttermilch über – bei zusätzlicher Vitamin-D-Gabe an den Säugling berücksichtigen.","hinweise":["Kautabletten kauen oder lutschen, am besten nach einer Mahlzeit.","Abstand zu Tetracyclinen, Chinolonen, Schilddrüsenhormonen, Bisphosphonaten und Eisen einhalten.","Keine weiteren Calcium- oder Vitamin-D-Präparate ohne ärztliche Absprache einnehmen."],"darreichung":["Kautabletten","Lutschtabletten","Brausetabletten"]},"calciumcarbonat-magnesiumcarbonat":{"wirkmechanismus":"Neutralisiert überschüssige Magensäure und lindert Sodbrennen innert Minuten. Calciumcarbonat und Magnesiumcarbonat reagieren mit der Salzsäure im Magen zu Calcium- bzw. Magnesiumchlorid, Wasser und Kohlendioxid und heben so den pH-Wert des Mageninhalts an. Magnesium wirkt leicht abführend, Calcium eher verstopfend. Ein Teil des Calciums und Magnesiums wird ins Blut aufgenommen und über die Nieren ausgeschieden.","nebenwirkungen":{"unbekannt":["Überempfindlichkeitsreaktionen (Hautausschlag, Nesselsucht, Juckreiz, Anaphylaxie)","Übelkeit, Erbrechen, Magenbeschwerden","Durchfall oder Verstopfung","Hyperkalzämie und Alkalose bei langer, hochdosierter Einnahme (Milch-Alkali-Syndrom)","Hypermagnesiämie (erhöhtes Magnesium im Blut), v. a. bei Niereninsuffizienz","Muskelschwäche als Zeichen eines erhöhten Calcium- oder Magnesiumspiegels"]},"schwangerschaft":"Kann in der Schwangerschaft in der empfohlenen Dosis kurzfristig angewendet werden; eine übermässige Calciumzufuhr (zusätzlich viel Milch oder Calciumpräparate) vermeiden.","stillzeit":"In der empfohlenen Dosierung möglich.","hinweise":["Tabletten bei Bedarf lutschen oder kauen; Tageshöchstdosis gemäss Packungsbeilage nicht überschreiten.","Zu anderen Arzneimitteln 2 Stunden Abstand halten, zu Chinolon-Antibiotika mindestens 4 Stunden.","Ohne ärztlichen Rat nicht länger als 2 Wochen einnehmen."],"darreichung":["Kau- und Lutschtabletten"]},"candesartan":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Wirkung des gefässverengenden Hormons Angiotensin II an seinem Rezeptor blockiert. Candesartancilexetil wird bei der Aufnahme im Darm vollständig zu Candesartan aktiviert, das sehr fest und lang anhaltend an den AT1-Rezeptor bindet. Dadurch weiten sich die Gefässe, die Aldosteronausschüttung sinkt und die Niere scheidet mehr Salz und Wasser aus, was Herz und Gefässe entlastet. Candesartan wird kaum verstoffwechselt und über Niere und Galle ausgeschieden; Reizhusten ist selten, da der Bradykinin-Abbau nicht beeinflusst wird.","nebenwirkungen":{"haeufig":["Atemwegsinfektionen","Schwindel, Drehschwindel","Kopfschmerzen","Hypotonie (tiefer Blutdruck) – vor allem bei Herzschwäche","Hyperkaliämie (erhöhtes Kalium) – vor allem bei Herzschwäche","Nierenfunktionsstörung, Kreatininanstieg – vor allem bei Herzschwäche"],"sehrSelten":["Leukopenie, Neutropenie, Agranulozytose (Mangel an weissen Blutkörperchen)","Hyponatriämie (Natriummangel)","Husten","Übelkeit","Erhöhte Leberwerte, Hepatitis","Angioödem (Schwellung von Gesicht, Lippen, Zunge, Rachen), Hautausschlag, Nesselsucht, Juckreiz","Rücken-, Gelenk- und Muskelschmerzen","Nierenversagen bei empfindlichen Patienten"],"unbekannt":["Durchfall"]},"schwangerschaft":"Im 1. Drittel nicht empfohlen; im 2. und 3. Drittel kontraindiziert, da fruchtschädigend (Nierenschäden, Fruchtwassermangel, verzögerte Schädelverknöcherung). Bei Kinderwunsch oder festgestellter Schwangerschaft rasch ärztlich auf ein anderes Mittel umstellen.","stillzeit":"Nicht empfohlen, da Daten zum Übergang in die Muttermilch fehlen; besser untersuchte Alternativen wählen.","hinweise":["Einmal täglich, unabhängig von den Mahlzeiten.","Kalium und Nierenwerte regelmässig kontrollieren; kaliumhaltige Salzersatzmittel und Kaliumpräparate nur nach ärztlicher Rücksprache.","Zu Beginn kann Schwindel auftreten – Vorsicht beim Autofahren.","Bei starkem Durchfall, Erbrechen oder Flüssigkeitsmangel ärztlich klären, ob die Einnahme vorübergehend pausiert werden soll."],"darreichung":["Tabletten"]},"carbimazol":{"wirkmechanismus":"Bremst die Bildung von Schilddrüsenhormonen und normalisiert so den Stoffwechsel bei einer Überfunktion. Carbimazol wird im Körper rasch und vollständig in den Wirkstoff Thiamazol (Methimazol) umgewandelt. Thiamazol hemmt die Thyreoperoxidase, das Enzym, das Jod in das Speichereiweiss Thyreoglobulin einbaut und die Hormonvorstufen zu T4 und T3 verknüpft. Bereits gebildetes, gespeichertes Hormon wird nicht beeinflusst; deshalb setzt die Wirkung erst nach 1–3 Wochen ein, die volle Wirkung oft erst nach 4–8 Wochen.","nebenwirkungen":{"haeufig":["Allergische Hautreaktionen (Ausschlag, Juckreiz, Nesselsucht)","Gelenkschmerzen","Übelkeit, leichte Magen-Darm-Beschwerden","Kopfschmerzen"],"gelegentlich":["Agranulozytose (starker Mangel an weissen Blutkörperchen) mit Fieber, Halsschmerzen und Infektionen, meist in den ersten Behandlungsmonaten","Arzneimittelfieber"],"sehrSelten":["Leberschäden (Gallenstau mit Gelbsucht, Hepatitis)","Aplastische Anämie, Thrombozytopenie, Panzytopenie (Mangel an allen Blutzellen)","Schwere Hautreaktionen (z. B. Stevens-Johnson-Syndrom)","Haarausfall","Insulin-Autoimmunsyndrom mit Unterzuckerung","Vaskulitis, Lupus-ähnliche Reaktionen, Nervenentzündungen","Geschmacks- und Geruchsstörungen"],"unbekannt":["Akute Pankreatitis (Bauchspeicheldrüsenentzündung)","Angioödem","Schilddrüsenunterfunktion und Kropfwachstum bei zu hoher Dosis"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung in der niedrigsten wirksamen Dosis und ohne zusätzliches Levothyroxin. Im ersten Schwangerschaftsdrittel kann Carbimazol Fehlbildungen verursachen (z. B. Hautdefekte am Kopf, Fehlbildungen von Gesicht, Speiseröhre oder Bauchwand); in dieser Zeit wird meist ein anderes Thyreostatikum bevorzugt.","stillzeit":"Geht in die Muttermilch über. Stillen ist nur nach ärztlicher Abwägung bei niedriger Dosis und mit Kontrolle der Schilddrüsenwerte des Kindes möglich.","hinweise":["Bei Fieber, Halsschmerzen, Mundgeschwüren oder grippeähnlichen Beschwerden sofort ärztliche Hilfe suchen und das Blutbild bestimmen lassen.","Regelmässige Kontrollen von Schilddrüsenwerten, Blutbild und Leberwerten.","Frauen im gebärfähigen Alter sollen während der Behandlung zuverlässig verhüten.","Die Wirkung setzt erst nach einigen Wochen ein; nicht eigenmächtig absetzen."],"darreichung":["Tabletten"]},"carvedilol":{"wirkmechanismus":"Senkt Blutdruck und Puls und entlastet das Herz, indem es die Wirkung der Stresshormone dämpft und gleichzeitig die Blutgefässe weitet. Carvedilol blockiert nicht selektiv die Beta-1- und Beta-2-Adrenozeptoren und senkt so Herzfrequenz, Kontraktionskraft und Reninfreisetzung. Die zusätzliche Blockade der Alpha-1-Rezeptoren in den Gefässwänden erweitert die Gefässe und senkt den peripheren Widerstand. Carvedilol wird in der Leber vor allem über CYP2D6 und CYP2C9 abgebaut.","nebenwirkungen":{"sehrHaeufig":["Schwindel","Kopfschmerzen","Müdigkeit und Schwäche (Asthenie)","Hypotonie (tiefer Blutdruck)","Verschlechterung einer Herzschwäche, vor allem zu Beginn und bei Dosiserhöhung"],"haeufig":["Bradykardie (langsamer Puls), Ödeme (Wassereinlagerungen)","Blutdruckabfall beim Aufstehen, kalte Hände und Füsse","Atemnot; Asthmaanfälle bei entsprechender Veranlagung","Bronchitis, Lungenentzündung, Harnwegsinfekte","Übelkeit, Erbrechen, Durchfall, Bauchschmerzen","Depression, depressive Verstimmung","Sehstörungen, verminderter Tränenfluss (trockene Augen)","Schlechtere Blutzuckereinstellung bei Diabetes, Gewichtszunahme; Verschlechterung der Nierenfunktion bei Gefässerkrankung oder Nierenschwäche"],"gelegentlich":["AV-Block, Angina pectoris","Synkope (Ohnmacht), Kribbeln (Parästhesien)","Schlafstörungen","Hautreaktionen (Ausschlag, Juckreiz, Nesselsucht, psoriasisartige Veränderungen), Haarausfall","Erektionsstörungen","Verstopfung"],"selten":["Thrombozytopenie (Mangel an Blutplättchen)","Verstopfte Nase","Mundtrockenheit"],"sehrSelten":["Leukopenie (Mangel an weissen Blutkörperchen)","Allergische Reaktionen","Erhöhte Leberwerte","Harninkontinenz bei Frauen","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, Erythema multiforme)"],"unbekannt":["Halluzinationen","Vermehrtes Schwitzen"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit nach ärztlicher Abwägung: Betablocker können die Durchblutung der Plazenta vermindern und das Wachstum des Kindes hemmen. Neugeborene in den ersten Lebenstagen auf langsamen Puls, Unterzuckerung und Atemprobleme überwachen.","stillzeit":"Stillen wird nicht empfohlen; Carvedilol und seine Abbauprodukte gehen (im Tierversuch) in die Muttermilch über.","hinweise":["Mit einer Mahlzeit einnehmen – bei Herzschwäche verringert das Schwindel und Blutdruckabfall beim Aufstehen.","Nicht abrupt absetzen (Gefahr von Angina-pectoris-Anfällen und Blutdruckanstieg); ein Absetzen erfolgt schrittweise nach ärztlicher Anweisung.","Zu Beginn und bei Dosiserhöhung Schwindel und Müdigkeit möglich; Vorsicht beim Autofahren, Alkohol verstärkt dies.","Bei Herzschwäche täglich wiegen: rasche Gewichtszunahme oder zunehmende Atemnot ärztlich melden."],"darreichung":["Tabletten"]},"caspofungin":{"wirkmechanismus":"Schädigt die Zellwand von Pilzen, sodass diese platzen oder nicht mehr wachsen können. Caspofungin hemmt nicht-kompetitiv das Enzym β-(1,3)-D-Glucan-Synthase, das einen wesentlichen Baustein der Pilzzellwand herstellt; menschliche Zellen besitzen dieses Enzym nicht. Gegen Candida wirkt es abtötend, gegen Aspergillus hemmt es das Wachstum der Pilzfäden. Caspofungin wird nicht über Cytochrom-P450 abgebaut und hat daher wenige Wechselwirkungen.","nebenwirkungen":{"haeufig":["Abfall von Hämoglobin, Hämatokrit und weissen Blutkörperchen","Hypokaliämie (Kaliummangel)","Kopfschmerzen","Venenentzündung an der Infusionsstelle (Phlebitis)","Atemnot","Übelkeit, Durchfall, Erbrechen","Erhöhte Leberwerte (ALT, AST, alkalische Phosphatase, Bilirubin)","Ausschlag, Juckreiz, Hautrötung, Schwitzen, Gelenkschmerzen, Fieber, Schüttelfrost"],"gelegentlich":["Anämie, Thrombozytopenie, Gerinnungsstörungen","Flüssigkeitsüberladung, Hypomagnesiämie, Hyperglykämie, Appetitlosigkeit","Angst, Schlaflosigkeit, Verwirrtheit","Schwindel, Geschmacksstörungen, Kribbeln, Zittern","Herzrhythmusstörungen (z. B. Vorhofflimmern), Herzklopfen, Herzinsuffizienz","Blutdruckabfall oder -anstieg, Hitzewallungen","Bronchospasmus, Husten","Bauchschmerzen, Verstopfung, Verdauungsbeschwerden","Cholestase, Gelbsucht, Leberfunktionsstörung","Nesselsucht, Erythema multiforme","Muskelschmerzen, Nierenfunktionsstörung bis akutes Nierenversagen"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse","Akutes Atemnotsyndrom (ARDS)","Hyperkalzämie","Periphere Ödeme"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur bei eindeutiger Notwendigkeit anwenden.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Wird im Spital einmal täglich als Infusion über etwa 1 Stunde verabreicht.","Ausschlag, Schwellungen, Juckreiz, Wärmegefühl oder Atemnot während der Infusion sofort melden.","Leberwerte und Elektrolyte werden während der Behandlung kontrolliert."],"darreichung":["Pulver zur Herstellung einer Infusionslösung"]},"cefazolin":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand verhindert. Cefazolin hemmt die Penicillin-bindenden Proteine und damit die Quervernetzung des Peptidoglykans (bakterizide Wirkung). Als Cephalosporin der 1. Generation wirkt es besonders gut gegen grampositive Keime wie Methicillin-empfindliche Staphylokokken und Streptokokken, gegen gramnegative Erreger nur begrenzt. Gegen MRSA und Enterokokken ist es unwirksam.","nebenwirkungen":{"haeufig":["Übelkeit, Erbrechen, Appetitlosigkeit, Durchfall, Bauchschmerzen","Schmerzen an der Einstichstelle, Venenentzündung (Phlebitis) bei Infusion"],"gelegentlich":["Hautausschlag, Nesselsucht, Juckreiz","Pilzinfektion von Mund oder Scheide (Candidose)"],"selten":["Blutbildveränderungen (Leukopenie, Neutropenie, Thrombozytopenie, Eosinophilie)","Vorübergehender Anstieg der Leberwerte","Nierenfunktionsstörung, interstitielle Nephritis (Nierenentzündung)","Anaphylaxie (schwere allergische Reaktion)"],"sehrSelten":["Pseudomembranöse Kolitis (schwere Darmentzündung)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Hämolytische Anämie (Blutzerfall)"],"unbekannt":["Krampfanfälle bei hohen Dosen und eingeschränkter Nierenfunktion","Gerinnungsstörungen mit Blutungen (Hypoprothrombinämie)","Positiver Coombs-Test"]},"schwangerschaft":"Kann angewendet werden, wenn nötig; breite Erfahrung, z. B. als Infektionsvorbeugung beim Kaiserschnitt, ohne Hinweise auf eine Schädigung des Kindes.","stillzeit":"Geht nur in sehr geringen Mengen in die Muttermilch über; die Anwendung ist möglich (beim Säugling Durchfall oder Pilzbefall möglich).","hinweise":["Wird im Spital oder in der Praxis als Injektion oder Infusion gegeben.","Allergien gegen Penicilline oder Cephalosporine vor der Gabe unbedingt melden.","Bei längerer Behandlung Blutbild und Nierenwerte kontrollieren."],"darreichung":["Pulver zur Herstellung einer Injektions- oder Infusionslösung"]},"cefpodoxim":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand verhindert. Cefpodoxim-Proxetil ist eine Vorstufe (Prodrug), die beim Durchtritt durch die Darmwand zum wirksamen Cefpodoxim gespalten wird. Dieses hemmt die Penicillin-bindenden Proteine und damit die Quervernetzung des Peptidoglykans (bakterizide Wirkung). Es ist gegen viele Beta-Laktamasen stabil und wirkt gegen Streptokokken, Pneumokokken, Haemophilus influenzae, Moraxella und viele E.-coli-Stämme; gegen Staphylokokken nur mässig, gegen Pseudomonas, Enterokokken und MRSA nicht.","nebenwirkungen":{"haeufig":["Durchfall, Übelkeit, Erbrechen, Bauchschmerzen, Blähungen"],"gelegentlich":["Kopfschmerzen, Schwindel, Kribbeln (Parästhesien)","Hautausschlag, Nesselsucht, Juckreiz","Müdigkeit, Schwäche"],"selten":["Blutbildveränderungen (Abfall des Hämoglobins, Thrombozytose, Thrombozytopenie, Leukopenie, Eosinophilie)","Anstieg von Leber- und Nierenwerten"],"sehrSelten":["Hämolytische Anämie (Blutzerfall)","Anaphylaxie, Angioödem, Bronchospasmus","Pseudomembranöse Kolitis (schwere Darmentzündung)","Leberschädigung (meist mit Gallestau)","Schwere Hautreaktionen (Erythema multiforme, Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)"],"unbekannt":["Pilzinfektionen (Mund, Scheide)","Ohrensausen (Tinnitus)"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; im Tierversuch keine Hinweise auf eine Schädigung, Erfahrungen beim Menschen begrenzt.","stillzeit":"Geht in die Muttermilch über; nur nach ärztlicher Abwägung anwenden oder abstillen.","hinweise":["Tabletten mit einer Mahlzeit einnehmen – so wird Cefpodoxim besser aufgenommen.","Antazida und andere säurebindende Mittel mit 2–3 Stunden Abstand einnehmen.","Die verordnete Behandlungsdauer einhalten; bei Hautausschlag oder schwerem Durchfall ärztlichen Rat einholen."],"darreichung":["Filmtabletten","Granulat für Suspension zum Einnehmen"]},"ceftazidim":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand verhindert. Ceftazidim hemmt die Penicillin-bindenden Proteine und damit die Quervernetzung des Peptidoglykans (bakterizide Wirkung). Es wirkt vor allem gegen gramnegative Bakterien einschliesslich Pseudomonas aeruginosa, gegen grampositive Keime wie Staphylokokken dagegen nur schwach. Bakterien mit Beta-Laktamasen vom ESBL- oder AmpC-Typ sowie Carbapenemase-Bildner sind meist resistent. Ceftazidim wird fast unverändert über die Niere ausgeschieden.","nebenwirkungen":{"haeufig":["Eosinophilie, Thrombozytose (Vermehrung der Blutplättchen)","Venenentzündung (Phlebitis) bei Infusion, Schmerzen und Entzündung an der Einstichstelle","Durchfall","Vorübergehender Anstieg der Leberwerte","Hautausschlag (fleckig oder mit Quaddeln)","Positiver Coombs-Test"],"gelegentlich":["Pilzinfektionen (Candidose)","Leukopenie, Neutropenie, Thrombozytopenie","Kopfschmerzen, Schwindel","Antibiotika-assoziierte Kolitis, Bauchschmerzen, Übelkeit, Erbrechen","Juckreiz, Fieber","Vorübergehender Anstieg der Nierenwerte"],"sehrSelten":["Interstitielle Nephritis (Nierenentzündung), akutes Nierenversagen"],"unbekannt":["Agranulozytose, hämolytische Anämie, Lymphozytose","Anaphylaxie (schwere allergische Reaktion bis zum Schock)","Neurologische Störungen bei eingeschränkter Nierenfunktion (Zittern, Muskelzuckungen, Krampfanfälle, Enzephalopathie, Koma)","Kribbeln (Parästhesien), Geschmacksstörung","Gelbsucht","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS), Angioödem"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung; im Tierversuch keine Hinweise auf eine Schädigung, Erfahrungen beim Menschen begrenzt.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Anwendung nach ärztlicher Abwägung möglich.","hinweise":["Wird im Spital als Injektion oder Infusion gegeben.","Bei eingeschränkter Nierenfunktion wird die Dosis angepasst; Verwirrtheit oder Muskelzuckungen sofort melden.","Allergien gegen Penicilline oder Cephalosporine vor der Behandlung angeben."],"darreichung":["Pulver zur Herstellung einer Injektions- oder Infusionslösung"]},"ceftriaxon":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand verhindert. Ceftriaxon hemmt die Penicillin-bindenden Proteine und damit die Quervernetzung des Peptidoglykans (bakterizide Wirkung). Es wirkt gegen viele grampositive und gramnegative Bakterien wie Pneumokokken, Streptokokken, Meningokokken, Gonokokken, Haemophilus und zahlreiche Darmbakterien und dringt gut in die Hirnhäute ein. Dank seiner langen Halbwertszeit (etwa 8 Stunden) genügt meist eine Gabe pro Tag; ausgeschieden wird es etwa je zur Hälfte über Niere und Galle. Gegen Pseudomonas, Enterokokken, MRSA und ESBL-Bildner ist es nicht zuverlässig wirksam.","nebenwirkungen":{"haeufig":["Eosinophilie, Leukopenie, Thrombozytopenie","Durchfall, weicher Stuhl","Anstieg der Leberwerte","Hautausschlag"],"gelegentlich":["Pilzinfektion im Genitalbereich","Granulozytopenie, Anämie, Gerinnungsstörung","Kopfschmerzen, Schwindel","Übelkeit, Erbrechen","Juckreiz","Venenentzündung, Schmerzen an der Einstichstelle, Fieber","Anstieg des Kreatinins (Nierenwert)"],"selten":["Pseudomembranöse Kolitis (schwere Darmentzündung)","Bronchospasmus (Verkrampfung der Atemwege)","Nesselsucht (Urtikaria)","Blut oder Zucker im Urin, Ödeme, Schüttelfrost"],"unbekannt":["Hämolytische Anämie (Blutzerfall, auch schwer), Agranulozytose","Anaphylaxie (schwere allergische Reaktion bis zum Schock), Kounis-Syndrom","Ceftriaxon-Calcium-Ablagerungen in Gallenblase und Nieren, Gallenkolik, Pankreatitis","Krampfanfälle, Enzephalopathie","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, AGEP, DRESS)","Kernikterus (Bilirubin-Hirnschädigung) bei Neugeborenen","Jarisch-Herxheimer-Reaktion bei Borreliose oder Syphilis"]},"schwangerschaft":"Passiert die Plazenta; nach ärztlicher Abwägung möglich, besonders im 1. Drittel nur bei klarer Notwendigkeit. Bisher keine Hinweise auf eine Schädigung des Kindes.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Anwendung möglich (beim Säugling Durchfall oder Pilzbefall möglich).","hinweise":["Wird als Injektion oder Infusion gegeben; die Zubereitung mit Lidocain darf nur in den Muskel gespritzt werden.","Starke Schmerzen im rechten Oberbauch, Blässe, dunkler Urin oder Atemnot während der Behandlung sofort melden.","Bei längerer Behandlung wird das Blutbild kontrolliert; ausreichend trinken."],"darreichung":["Pulver zur Herstellung einer Injektions- oder Infusionslösung","Pulver mit Lidocain-haltigem Lösungsmittel zur Injektion in den Muskel"]},"cefuroxim":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand verhindert. Cefuroxim hemmt die Penicillin-bindenden Proteine und damit die Quervernetzung des Peptidoglykans (bakterizide Wirkung). Es ist gegen viele Beta-Laktamasen stabil und wirkt gegen Streptokokken, Methicillin-empfindliche Staphylokokken, Haemophilus influenzae, Moraxella sowie einen Teil der Darmbakterien wie E. coli. Die Tablettenform Cefuroxim-Axetil ist eine Vorstufe, die in der Darmwand zu Cefuroxim gespalten wird.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Schwindel","Durchfall, Übelkeit, Bauchschmerzen","Pilzinfektionen (z. B. Mund oder Scheide)","Eosinophilie (Vermehrung bestimmter weisser Blutkörperchen)","Vorübergehender Anstieg der Leberwerte","Bei Infusion: Schmerzen oder Venenentzündung an der Einstichstelle"],"gelegentlich":["Erbrechen","Hautausschlag","Thrombozytopenie, Leukopenie","Positiver Coombs-Test"],"unbekannt":["Clostridioides-difficile-Infektion, pseudomembranöse Kolitis (schwere Darmentzündung)","Hämolytische Anämie (Blutzerfall)","Anaphylaxie, Arzneimittelfieber, Serumkrankheit","Jarisch-Herxheimer-Reaktion","Gelbsucht (meist durch Gallestau), Leberentzündung","Nesselsucht, Juckreiz, Angioödem","Schwere Hautreaktionen (Erythema multiforme, Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Interstitielle Nephritis, Anstieg der Nierenwerte (Infusion)"]},"schwangerschaft":"Nach ärztlicher Abwägung möglich; bisher keine Hinweise auf eine Schädigung des Kindes.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Anwendung nach Abwägung möglich (beim Säugling Durchfall oder Pilzbefall möglich).","hinweise":["Tabletten nach einer Mahlzeit einnehmen – so werden sie besser aufgenommen; nicht zerkauen oder zerdrücken (sehr bitterer Geschmack).","Die verordnete Behandlungsdauer einhalten.","Kann Schwindel verursachen – Vorsicht beim Autofahren und Bedienen von Maschinen.","Bei Hautausschlag, Atemnot oder schwerem Durchfall ärztlichen Rat einholen."],"darreichung":["Filmtabletten","Granulat für Suspension zum Einnehmen","Pulver zur Herstellung einer Injektions- oder Infusionslösung"]},"chlorhexidin":{"wirkmechanismus":"Tötet Bakterien ab und hemmt Pilze auf Haut und Schleimhaut. Das positiv geladene Chlorhexidin bindet an die negativ geladene Zellwand der Mikroorganismen, macht die Zellmembran durchlässig und führt in höherer Konzentration zum Absterben der Keime. Es wirkt besonders gut gegen grampositive, etwas schwächer gegen gramnegative Bakterien und Hefepilze, gegen Sporen kaum. Weil es an Zähnen und Schleimhaut haftet und langsam wieder freigesetzt wird, hält die Wirkung im Mund mehrere Stunden an (Depotwirkung).","nebenwirkungen":{"haeufig":["Bräunliche Verfärbungen von Zähnen, Füllungen, Prothesen und Zunge (rückbildungsfähig, durch professionelle Zahnreinigung entfernbar)","Belegte Zunge","Vorübergehende Geschmacksstörungen","Brennen oder Taubheitsgefühl der Zunge"],"selten":["Überempfindlichkeitsreaktionen der Haut (Ausschlag, Rötung, Juckreiz)"],"sehrSelten":["Anaphylaxie (schwere allergische Reaktion bis zum Schock)"],"unbekannt":["Reizung oder Abschuppung der Mundschleimhaut","Rückbildungsfähige Schwellung der Ohrspeicheldrüse","Vermehrte Zahnsteinbildung","Hautreizung oder Kontaktekzem bei Anwendung auf der Haut","Hautverätzungen bei Frühgeborenen"]},"schwangerschaft":"Bei Anwendung im Mund oder auf der Haut wird kaum Wirkstoff ins Blut aufgenommen; die Anwendung in der Schwangerschaft ist möglich.","stillzeit":"Anwendung in der Stillzeit möglich; nicht im Bereich der Brust anwenden, damit der Säugling den Wirkstoff nicht aufnimmt.","hinweise":["Mundspülung nach dem Spülen ausspucken und nicht schlucken; nicht unmittelbar nach dem Zähneputzen anwenden.","Kaffee, Tee, Rotwein und Rauchen verstärken die Verfärbungen der Zähne.","Ohne zahnärztlichen Rat die Mundspülung nicht länger als etwa 2 Wochen anwenden.","Bei Kontakt mit den Augen sofort gründlich mit Wasser spülen."],"darreichung":["Mundspüllösung","Lösung und Spray zur Haut- und Wunddesinfektion","Crème und Spray (Kombination mit Dexpanthenol)"]},"chlortalidon":{"wirkmechanismus":"Fördert die Ausscheidung von Salz und Wasser über die Niere und senkt so den Blutdruck. Chlortalidon hemmt wie die Thiazide den Natrium-Chlorid-Cotransporter im frühdistalen Tubulus; dadurch werden mehr Natrium, Chlorid und Wasser, aber auch Kalium und Magnesium ausgeschieden, Calcium dagegen zurückgehalten. Die Dauerwirkung auf den Blutdruck beruht zusätzlich auf einer Abnahme des Gefässwiderstands. Wegen der sehr langen Halbwertszeit von rund 50 Stunden (Bindung an die roten Blutkörperchen) hält die Wirkung 48–72 Stunden an.","nebenwirkungen":{"sehrHaeufig":["Hypokaliämie (Kaliummangel)","Hyperurikämie (erhöhte Harnsäure)","Erhöhte Blutfette, vor allem bei höheren Dosen"],"haeufig":["Hyponatriämie (Natriummangel), Hypomagnesiämie (Magnesiummangel)","Hyperglykämie (erhöhter Blutzucker)","Nesselsucht und andere Hautausschläge","Orthostatische Hypotonie (Schwindel beim Aufstehen), verstärkt durch Alkohol oder Beruhigungsmittel","Appetitlosigkeit, leichte Magen-Darm-Beschwerden","Erektionsstörungen","Schwindel"],"selten":["Hyperkalzämie (erhöhtes Calcium)","Verschlechterung eines Diabetes, Zucker im Urin, Gichtanfälle","Photosensibilität (Lichtempfindlichkeit der Haut)","Herzrhythmusstörungen","Übelkeit, Erbrechen, Bauchschmerzen, Verstopfung, Durchfall","Gallenstau in der Leber (intrahepatische Cholestase), Gelbsucht","Kopfschmerzen, Kribbeln (Parästhesien), Sehstörungen","Thrombozytopenie, Leukopenie, Agranulozytose, Eosinophilie"],"sehrSelten":["Hypochlorämische Alkalose","Pankreatitis (Bauchspeicheldrüsenentzündung)","Lungenödem als Überempfindlichkeitsreaktion","Allergische interstitielle Nephritis (Nierenentzündung)","Vaskulitis (Gefässentzündung)"],"unbekannt":["Akute Kurzsichtigkeit, Aderhauterguss, akutes Engwinkelglaukom"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit; nicht bei schwangerschaftsbedingten Ödemen, Bluthochdruck oder Präeklampsie, da es die Durchblutung der Plazenta vermindern und beim Neugeborenen Gelbsucht, Elektrolytstörungen und Blutplättchenmangel verursachen kann.","stillzeit":"Geht in die Muttermilch über und kann die Milchbildung hemmen; in der Stillzeit nicht anwenden.","hinweise":["Am Morgen einnehmen; die Wirkung hält 2–3 Tage an, deshalb kann sie nach dem Absetzen noch nachwirken.","Kalium, Natrium, Nierenwerte, Harnsäure und Blutzucker regelmässig kontrollieren lassen; bei Erbrechen, Durchfall oder starkem Schwitzen ärztlichen Rat einholen.","Haut vor starker Sonne schützen (Lichtempfindlichkeit).","Bei plötzlicher Sehverschlechterung oder Augenschmerzen sofort ärztliche Hilfe suchen."],"darreichung":["Tabletten"]},"ciclopirox":{"wirkmechanismus":"Hemmt das Wachstum von Pilzen und tötet sie ab. Ciclopirox bindet (chelatiert) dreiwertige Metallionen wie Eisen und Aluminium und blockiert dadurch eisenabhängige Enzyme, die der Pilz für seinen Stoffwechsel und die Entgiftung von Sauerstoffradikalen braucht. Es wirkt breit gegen Dermatophyten, Hefen und Schimmelpilze, zusätzlich gegen einige Bakterien, und dämpft Entzündungen leicht. Aus dem Nagellack dringt der Wirkstoff in die Nagelplatte ein.","nebenwirkungen":{"gelegentlich":["Brennen und Juckreiz an der Anwendungsstelle (Creme, Lösung)"],"sehrSelten":["Rötung und Schuppung der Haut rund um den behandelten Nagel (Nagellack)","Allergische Kontaktdermatitis (juckender Ausschlag an der Auftragsstelle)"]},"schwangerschaft":"Nur nach ärztlicher Abwägung: Es gibt kaum Erfahrungen, die Aufnahme in den Körper ist bei äusserlicher Anwendung aber gering.","stillzeit":"Nach ärztlicher Abwägung möglich, da kaum Wirkstoff in den Körper gelangt; nicht im Brustbereich auftragen.","hinweise":["Nagelpilz braucht Geduld: Die Behandlung dauert meist mehrere Monate (Fingernägel etwa 6, Zehennägel 9–12 Monate), bis der Nagel gesund nachgewachsen ist.","Während der Behandlung mit dem Nagellack keinen kosmetischen Nagellack und keine künstlichen Nägel verwenden.","Nicht in die Augen oder auf Schleimhäute bringen.","Keine Besserung nach etwa 6 Monaten: ärztlich kontrollieren lassen."],"darreichung":["Nagellack (wirkstoffhaltig)","Creme","Lösung zur Anwendung auf der Haut"]},"cimicifuga":{"wirkmechanismus":"Lindert typische Wechseljahresbeschwerden wie Hitzewallungen und Schweissausbrüche. Der Wirkmechanismus des Extrakts aus dem Wurzelstock der Traubensilberkerze ist nicht vollständig geklärt. Nach heutigem Wissen wirkt er nicht wie ein klassisches Östrogen auf Brust und Gebärmutterschleimhaut, sondern beeinflusst vermutlich zentrale Botenstoffsysteme (u. a. Serotonin- und Opioidrezeptoren), die an der Temperaturregulation beteiligt sind.","nebenwirkungen":{"unbekannt":["Magen-Darm-Beschwerden (Verdauungsbeschwerden, Durchfall)","Allergische Hautreaktionen (Nesselsucht, Juckreiz, Ausschlag)","Schwellungen im Gesicht, Wassereinlagerungen in Armen und Beinen (Ödeme)","Leberschädigung (Leberentzündung, Gelbsucht, veränderte Leberwerte), in Einzelfällen schwer"]},"schwangerschaft":"Nicht anwenden – keine ausreichenden Daten; das Mittel ist für Frauen in den Wechseljahren bestimmt.","stillzeit":"Nicht anwenden – keine ausreichenden Daten.","hinweise":["Die Wirkung setzt nach etwa 2 Wochen ein, die volle Wirkung oft erst nach mehreren Wochen.","Ohne ärztliche Rücksprache nicht länger als 6 Monate einnehmen.","Bei Anzeichen einer Leberschädigung (Gelbsucht, dunkler Urin, starke Müdigkeit, Oberbauchschmerzen) sofort absetzen und eine Ärztin oder einen Arzt aufsuchen.","Ersetzt keine ärztliche Abklärung von Blutungen nach der Menopause."],"darreichung":["Tabletten","Filmtabletten"]},"cinacalcet":{"wirkmechanismus":"Macht die Nebenschilddrüsen empfindlicher für Calcium, sodass sie weniger Parathormon ausschütten. Cinacalcet ist ein allosterischer Modulator des calciumsensitiven Rezeptors (CaSR) auf den Hauptzellen der Nebenschilddrüse: Schon niedrigere Calciumkonzentrationen hemmen dadurch die Parathormon-Freisetzung. In der Folge sinken Parathormon und Calcium im Blut, bei Dialysepatienten auch das Calcium-Phosphat-Produkt.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Erbrechen"],"haeufig":["Hypokalzämie (zu tiefes Calcium; z. B. Kribbeln, Muskelkrämpfe)","Krampfanfälle","Appetitlosigkeit","Schwindel, Kribbeln (Parästhesien), Kopfschmerzen","Blutdruckabfall (Hypotonie)","Durchfall, Verstopfung, Bauchschmerzen, Verdauungsbeschwerden","Muskelschmerzen, Muskelkrämpfe, Rückenschmerzen, Schwäche","Hautausschlag, Überempfindlichkeitsreaktionen, Hyperkaliämie (erhöhtes Kalium), tieferes Testosteron"],"unbekannt":["Verschlechterung einer Herzinsuffizienz","QT-Verlängerung und ventrikuläre Herzrhythmusstörungen infolge Hypokalzämie","Nesselsucht (Urtikaria)","Angioödem (Schwellung von Gesicht, Lippen oder Rachen)"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur anwenden, wenn der Nutzen das mögliche Risiko für das Kind klar überwiegt.","stillzeit":"Nicht bekannt, ob Cinacalcet in die Muttermilch übergeht; nach ärztlicher Abwägung entweder abstillen oder auf das Mittel verzichten.","hinweise":["Mit einer Mahlzeit oder kurz danach einnehmen – so wird Cinacalcet besser aufgenommen. Tabletten ganz schlucken, nicht teilen oder zerkauen.","Regelmässige Kontrollen von Calcium und Parathormon, besonders in den ersten Wochen und nach jeder Dosisänderung.","Kribbeln um den Mund oder in den Fingern, Muskelzuckungen, Krämpfe oder Krampfanfälle können Zeichen eines zu tiefen Calciums sein – sofort ärztlich melden.","Beginn oder Ende des Rauchens der Ärztin oder dem Arzt mitteilen."],"darreichung":["Filmtabletten"]},"ciprofloxacin":{"wirkmechanismus":"Tötet Bakterien ab, indem es das Kopieren ihrer Erbsubstanz verhindert. Ciprofloxacin hemmt die bakteriellen Topoisomerasen II (DNA-Gyrase) und IV, die zum Entwinden und Trennen der DNA nötig sind; es entstehen tödliche DNA-Brüche. Es wirkt besonders gut gegen gramnegative Erreger einschliesslich Pseudomonas aeruginosa, schwächer gegen Pneumokokken und kaum gegen Anaerobier. Ciprofloxacin hemmt zudem das Leberenzym CYP1A2.","nebenwirkungen":{"haeufig":["Übelkeit, Durchfall","Bei Augentropfen: Augenbeschwerden, weissliche Ablagerungen auf der Hornhaut"],"gelegentlich":["Pilzinfektionen","Kopfschmerzen, Schwindel, Schlafstörungen, Geschmacksstörungen, Unruhe","Erbrechen, Bauchschmerzen, Verdauungsbeschwerden, Blähungen","Erhöhte Leberwerte und Bilirubin","Hautausschlag, Juckreiz, Nesselsucht","Gelenkschmerzen (bei Kindern häufig)","Eosinophilie, Appetitlosigkeit, Schwäche, Fieber"],"selten":["Antibiotika-assoziierte Kolitis (sehr selten pseudomembranös)","Blutbildveränderungen (Leukopenie, Anämie, Thrombozytopenie)","Verwirrtheit, Angst, Albträume, Depression bis Suizidgedanken, Halluzinationen","Krampfanfälle, Kribbeln und Missempfindungen, Zittern","Sehstörungen, Tinnitus, Hörverlust","Herzrasen, Blutdruckabfall, Ohnmacht","Unter- oder Überzuckerung","Lichtempfindlichkeit der Haut, Muskelschmerzen, Nierenversagen, Kristallurie"],"sehrSelten":["Sehnenentzündung und Sehnenriss (vor allem Achillessehne), Muskelschwäche, Verschlechterung einer Myasthenia gravis","Agranulozytose, hämolytische Anämie, Panzytopenie","Anaphylaktischer Schock","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Lebernekrose bis Leberversagen, Pankreatitis","Psychotische Reaktionen, Gangstörungen, erhöhter Hirndruck"],"unbekannt":["QT-Verlängerung, ventrikuläre Herzrhythmusstörungen, Torsade de pointes","Periphere Neuropathie (teils bleibend)","Aortenaneurysma und -dissektion, Herzklappenundichtigkeit","DRESS und akute generalisierte exanthematische Pustulose","Hyponatriämie (SIADH), Manie","Lang anhaltende, möglicherweise bleibende Nebenwirkungen an Sehnen, Muskeln, Gelenken, Nerven und Psyche"]},"schwangerschaft":"Vorsichtshalber nicht anwenden, da in Tierversuchen Gelenkknorpelschäden beim Jungtier auftraten. Augen- und Ohrentropfen nur nach ärztlicher Abwägung.","stillzeit":"Geht in die Muttermilch über; wegen möglicher Gelenkknorpelschäden beim Säugling während der systemischen Behandlung nicht stillen.","hinweise":["Nicht zusammen mit Milch, Joghurt oder mit Calcium angereicherten Säften allein einnehmen; Abstand zu Mineralstoff- und Eisenpräparaten sowie Antazida einhalten.","Bei Sehnenschmerzen, Kribbeln, Taubheit, plötzlichen Brust-, Bauch- oder Rückenschmerzen sofort absetzen und ärztliche Hilfe holen.","Starke Sonne und Solarium meiden; das Reaktionsvermögen kann eingeschränkt sein (Autofahren).","Kaffee wirkt stärker und länger."],"darreichung":["Filmtabletten","Suspension zum Einnehmen","Infusionslösung","Augentropfen","Ohrentropfen"]},"clarithromycin":{"wirkmechanismus":"Hemmt das Wachstum von Bakterien, indem es ihre Eiweissherstellung stoppt. Clarithromycin bindet an die 50S-Untereinheit der bakteriellen Ribosomen und blockiert die Verlängerung der Eiweisskette; sein Hauptmetabolit 14-Hydroxy-Clarithromycin ist ebenfalls wirksam. Es wirkt gegen Streptokokken, Haemophilus, atypische Erreger (Mykoplasmen, Chlamydien, Legionellen), Helicobacter pylori und Mykobakterien. Clarithromycin hemmt das Abbauenzym CYP3A4 und den Transporter P-Glykoprotein stark und erhöht dadurch die Spiegel vieler anderer Medikamente.","nebenwirkungen":{"haeufig":["Geschmacksstörungen, Kopfschmerzen","Schlaflosigkeit","Durchfall, Übelkeit, Erbrechen, Bauchschmerzen, Verdauungsbeschwerden","Hautausschlag, vermehrtes Schwitzen","Abweichende Leberwerte","Venenentzündung an der Infusionsstelle"],"gelegentlich":["Pilzinfektionen (Candidose), Scheideninfektion","Leukopenie, Neutropenie, Eosinophilie (Blutbildveränderungen)","Schwindel, Drehschwindel, Schläfrigkeit, Zittern, Angst","Hörstörungen, Tinnitus (Ohrensausen)","QT-Verlängerung im EKG, Herzklopfen","Gastritis, Verstopfung, Mundtrockenheit, Blähungen","Cholestase und Hepatitis (Leberentzündung)","Juckreiz, Nesselsucht, Muskelschmerzen"],"unbekannt":["Torsade de pointes, Kammertachykardie und Kammerflimmern","Pseudomembranöse Kolitis (schwere Dickdarmentzündung)","Agranulozytose (starker Mangel an weissen Blutkörperchen), Thrombozytopenie","Anaphylaxie, Angioödem","Leberversagen","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS, AGEP)","Verwirrtheit, Halluzinationen, Psychosen, Krampfanfälle, Hörverlust","Rhabdomyolyse (Muskelzerfall), Nierenversagen, interstitielle Nephritis"]},"schwangerschaft":"Die Sicherheit ist nicht belegt; Tierversuche zeigen schädliche Wirkungen. Nur nach sorgfältiger ärztlicher Nutzen-Risiko-Abwägung anwenden.","stillzeit":"Geht in die Muttermilch über; beim Säugling sind Durchfall und Pilzbefall möglich. Nur nach ärztlicher Abwägung.","hinweise":["Vor Beginn alle anderen Medikamente angeben: Clarithromycin hat sehr viele, teils lebensgefährliche Wechselwirkungen.","Retardtabletten mit einer Mahlzeit und unzerkaut schlucken.","Bei Herzklopfen, Ohnmacht, Gelbsucht, dunklem Urin oder starkem Durchfall sofort ärztliche Hilfe holen."],"darreichung":["Filmtabletten","Retardtabletten","Granulat für Suspension zum Einnehmen","Pulver zur Herstellung einer Infusionslösung"]},"clindamycin":{"wirkmechanismus":"Hemmt das Wachstum von Bakterien, indem es ihre Eiweissherstellung stoppt. Clindamycin bindet an die 50S-Untereinheit der bakteriellen Ribosomen und hemmt die Peptidkettenbildung; es wirkt vorwiegend bakteriostatisch gegen grampositive Kokken (Staphylokokken, Streptokokken) und Anaerobier. Es dringt gut in Knochen und Gewebe ein und hemmt die Toxinbildung von Streptokokken und Staphylokokken. Gegen Enterokokken und die meisten gramnegativen Keime wirkt es nicht.","nebenwirkungen":{"haeufig":["Durchfall, Bauchschmerzen","Pseudomembranöse Kolitis (schwere Dickdarmentzündung durch Clostridioides difficile)","Fleckiger Hautausschlag","Abweichende Leberwerte","Venenentzündung bei Infusion","Bei Anwendung auf der Haut: Trockenheit, Rötung, Brennen; bei Vaginalcreme: Scheidenpilz"],"gelegentlich":["Übelkeit, Erbrechen","Geschmacksstörungen","Nesselsucht"],"selten":["Erythema multiforme (Hautausschlag mit kokardenförmigen Flecken)","Juckreiz"],"unbekannt":["Agranulozytose, Neutropenie, Thrombozytopenie (Blutbildschäden)","Anaphylaxie, Angioödem","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS, AGEP)","Gelbsucht","Speiseröhrenentzündung oder -geschwür bei Kapseln","Akute Nierenschädigung"]},"schwangerschaft":"Im 2. und 3. Drittel zeigten Studien kein erhöhtes Fehlbildungsrisiko; für das 1. Drittel sind die Daten begrenzt. Nur bei klarer Notwendigkeit nach ärztlicher Abwägung; die Anwendung auf der Haut gilt als vertretbar.","stillzeit":"Geht in die Muttermilch über; beim Säugling sind Durchfall, Pilzbefall und selten blutiger Stuhl möglich. Nach ärztlicher Abwägung, Kind beobachten.","hinweise":["Kapseln aufrecht mit einem vollen Glas Wasser schlucken (Gefahr einer Speiseröhrenreizung).","Bei starkem, anhaltendem oder blutigem Durchfall – auch Wochen nach der Behandlung – sofort ärztliche Hilfe holen; keine stopfenden Mittel wie Loperamid nehmen.","Vaginalcreme kann Kondome und Diaphragmen aus Latex beschädigen.","Akne-Kombinationen mit Benzoylperoxid können Textilien und Haare bleichen."],"darreichung":["Kapseln","Injektions- und Infusionslösung","Lösung und Gel zum Auftragen auf die Haut","Vaginalcreme"]},"clobetasol":{"wirkmechanismus":"Hemmt Entzündung, Juckreiz und übermässige Zellteilung in der Haut sehr stark. Clobetasolpropionat bindet an den Glukokortikoid-Rezeptor der Hautzellen und unterdrückt die Bildung entzündungsfördernder Botenstoffe; zusätzlich verengt es die kleinen Hautgefässe und bremst die Vermehrung der Hautzellen (antiproliferative Wirkung). Es gehört zu den stärksten äusserlich angewendeten Kortikosteroiden (Klasse IV) und kann bei grossflächiger oder langer Anwendung in relevanter Menge in den Körper gelangen.","nebenwirkungen":{"haeufig":["Juckreiz","Brennen oder Schmerzen der Haut an der Auftragsstelle"],"gelegentlich":["Hautverdünnung (Atrophie)","Dehnungsstreifen (Striae)","Erweiterte Äderchen (Teleangiektasien)"],"sehrSelten":["Kortison-Wirkungen im ganzen Körper: Cushing-Syndrom, Nebennierenschwäche, erhöhter Blutzucker, Bluthochdruck, Wachstumsverzögerung bei Kindern","Grauer und grüner Star (Katarakt, Glaukom)","Opportunistische Hautinfektionen","Allergische Kontaktdermatitis und andere Überempfindlichkeitsreaktionen","Verschlechterung der Psoriasis, pustulöse Psoriasis","Pigmentveränderungen, vermehrte Behaarung, Akne, rosazeaartige Hautentzündung"],"unbekannt":["Verschwommenes Sehen (Chorioretinopathie)"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung, so kurz und kleinflächig wie möglich; in Tierversuchen traten nach Anwendung starker Kortikosteroide Fehlbildungen auf.","stillzeit":"Nach Abwägung kurzfristig und kleinflächig möglich; nicht auf die Brust auftragen.","hinweise":["Höchstens 50 g Creme oder Salbe pro Woche und in der Regel nicht länger als 4 Wochen anwenden.","Dünn auftragen und danach die Hände waschen; luftdichte Verbände nur auf ärztliche Anweisung.","Nach Besserung nicht abrupt absetzen, sondern ausschleichen oder auf ein schwächeres Präparat wechseln.","Shampoo (Clobex) auf die trockene Kopfhaut auftragen, 15 Minuten einwirken lassen und gründlich ausspülen."],"darreichung":["Creme","Salbe","Lösung für die Kopfhaut","Schaum","Shampoo"]},"clonidin":{"wirkmechanismus":"Senkt den Blutdruck, indem es im Gehirn die Signale des sympathischen Nervensystems an Herz und Gefässe drosselt. Clonidin stimuliert Alpha-2-Rezeptoren und Imidazolin-Rezeptoren im Hirnstamm; dadurch sinken die Ausschüttung von Noradrenalin, der Gefässwiderstand und die Herzfrequenz. Die zentrale Wirkung erklärt auch Müdigkeit und Mundtrockenheit. Nach plötzlichem Absetzen kann der Sympathikus überschiessend reagieren (Rebound-Hochdruck).","nebenwirkungen":{"sehrHaeufig":["Blutdruckabfall beim Aufstehen (orthostatische Hypotonie)","Schwindel","Müdigkeit, Sedierung","Mundtrockenheit"],"haeufig":["Depression, Schlafstörungen","Kopfschmerzen","Verstopfung, Übelkeit, Erbrechen","Schmerzen der Speicheldrüsen","Erektionsstörungen","Erschöpfung"],"gelegentlich":["Albträume, Wahnvorstellungen, Halluzinationen","Kribbeln (Parästhesien)","Sinusbradykardie","Raynaud-Syndrom (Weissfinger)","Juckreiz, Hautausschlag, Nesselsucht","Unwohlsein"],"selten":["AV-Block","Verminderter Tränenfluss","Darmlähmung (Pseudoobstruktion des Dickdarms)","Gynäkomastie (Brustvergrösserung beim Mann)","Haarausfall","Erhöhter Blutzucker"],"unbekannt":["Verwirrtheit","Verminderte Libido","Akkommodationsstörungen (Probleme beim Scharfsehen)","Bradyarrhythmie"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung; Clonidin gelangt zum Kind und kann beim Neugeborenen Blutdruck und Puls senken.","stillzeit":"Geht in die Muttermilch über; Anwendung in der Stillzeit nicht empfohlen.","hinweise":["Nie abrupt absetzen – sonst drohen starker Blutdruckanstieg, Herzrasen und Unruhe; immer über einige Tage ausschleichen.","Alkohol verstärkt die Müdigkeit; Fahrtüchtigkeit kann besonders zu Beginn eingeschränkt sein.","Langsam aufstehen, um Schwindel durch Blutdruckabfall zu vermeiden."],"darreichung":["Tabletten","Injektionslösung"]},"clopidogrel":{"wirkmechanismus":"Verhindert, dass Blutplättchen verklumpen und Gerinnsel in den Arterien bilden. Clopidogrel ist eine unwirksame Vorstufe (Prodrug), die in der Leber vor allem über das Enzym CYP2C19 in einen aktiven Metaboliten umgewandelt wird. Dieser blockiert den ADP-Rezeptor P2Y12 der Blutplättchen irreversibel und hemmt damit deren Aktivierung. Die Hemmung hält für die ganze Lebensdauer der Plättchen (7–10 Tage) an. Bei genetisch langsamer CYP2C19-Aktivität entsteht weniger Wirkstoff, die Wirkung ist dann schwächer.","nebenwirkungen":{"haeufig":["Blutergüsse (Hämatome), Hautblutungen","Nasenbluten","Magen-Darm-Blutungen","Durchfall, Bauchschmerzen, Verdauungsbeschwerden","Nachblutung an Punktionsstellen"],"gelegentlich":["Hirnblutung (teils tödlich)","Verminderung von Blutplättchen und weissen Blutkörperchen, Eosinophilie","Kopfschmerzen, Schwindel, Kribbeln","Magen- und Zwölffingerdarmgeschwüre, Gastritis, Übelkeit, Erbrechen, Verstopfung","Augenblutungen","Hautausschlag, Juckreiz","Blut im Urin"],"selten":["Neutropenie, auch schwere (Mangel an weissen Blutkörperchen)","Drehschwindel","Blutungen im hinteren Bauchraum (retroperitoneal)","Gynäkomastie (Brustvergrösserung beim Mann)"],"sehrSelten":["Thrombotisch-thrombozytopenische Purpura (TTP)","Agranulozytose, aplastische Anämie, Panzytopenie, schwere Thrombozytopenie","Erworbene Hämophilie A","Anaphylaktoide Reaktionen, Serumkrankheit, Angioödem","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS)","Akutes Leberversagen, Hepatitis, Pankreatitis","Schwere, auch tödliche Blutungen","Interstitielle oder eosinophile Pneumonie, Bronchospasmus"],"unbekannt":["Insulin-Autoimmunsyndrom mit schwerer Unterzuckerung","Kounis-Syndrom (allergisch ausgelöste Brustenge)","Kreuzallergie mit anderen Thienopyridinen"]},"schwangerschaft":"Keine ausreichenden Erfahrungen beim Menschen; vorsichtshalber in der Schwangerschaft nicht anwenden, ausser nach strenger ärztlicher Abwägung.","stillzeit":"Im Tierversuch Übergang in die Muttermilch; während der Behandlung nicht stillen.","hinweise":["Nicht eigenmächtig absetzen – besonders nach Stent-Einlage drohen Stentverschluss und Herzinfarkt.","Vor Operationen und Zahnbehandlungen die Einnahme angeben; ein Pausieren (meist 7 Tage vorher) nur nach ärztlicher Anordnung.","Als Magenschutz eignet sich eher Pantoprazol als Omeprazol oder Esomeprazol.","Bei Fieber, Schwäche, Verwirrtheit, Gelbsucht oder punktförmigen Hautblutungen sofort ärztliche Hilfe holen (TTP)."],"darreichung":["Filmtabletten"]},"clotrimazol":{"wirkmechanismus":"Hemmt das Wachstum von Pilzen, indem es den Aufbau ihrer Zellmembran stört. Clotrimazol blockiert das pilzeigene Enzym Lanosterol-14-alpha-Demethylase (ein Cytochrom-P450-Enzym) und damit die Bildung von Ergosterol, dem wichtigsten Baustein der Pilzzellmembran. Die Membran wird durchlässig; in niedriger Konzentration wirkt Clotrimazol wachstumshemmend (fungistatisch), in hoher abtötend (fungizid). Es wirkt gegen Dermatophyten, Hefen und Schimmelpilze sowie gegen einige grampositive Bakterien (z. B. Erreger des Erythrasmas). Auf Haut oder Schleimhaut aufgetragen gelangt nur sehr wenig Wirkstoff ins Blut.","nebenwirkungen":{"unbekannt":["Haut: Rötung, Brennen, Stechen, Juckreiz, Reizung, Schuppung, Bläschen, Schwellung","Scheide: Brennen, Juckreiz, Rötung, Schwellung, Beschwerden, Ausschlag","Unterleibsschmerzen, vaginale Blutungen","Allergische Reaktionen bis zu Kreislaufkollaps (Synkope, Blutdruckabfall), Atemnot, Nesselsucht"]},"schwangerschaft":"Kann nach ärztlicher Rücksprache angewendet werden (sehr geringe Aufnahme ins Blut). Vaginaltabletten in der Schwangerschaft ohne Applikator einführen.","stillzeit":"Anwendung möglich; nicht im Brustbereich auftragen bzw. die Haut vor dem Stillen gründlich reinigen.","hinweise":["Hautpilz: nach Abklingen der Beschwerden noch etwa 2 Wochen weiterbehandeln, um Rückfälle zu vermeiden.","Scheidenpilz: abends tief in die Scheide einführen; die Behandlung nicht während der Menstruation durchführen. Den Partner bei Beschwerden mitbehandeln.","Latex-Kondome und Diaphragmen sind während und bis mindestens 5 Tage nach vaginaler Anwendung nicht sicher.","Nicht in die Augen bringen und nicht einnehmen; Handtücher und Wäsche häufig wechseln und heiss waschen."],"darreichung":["Creme","Lösung","Paste","Vaginaltabletten","Vaginalcreme"]},"colecalciferol-vitamin-d3":{"wirkmechanismus":"Stellt dem Körper Vitamin D zur Verfügung, das er für die Aufnahme von Calcium und gesunde Knochen braucht. Colecalciferol ist eine Vorstufe: In der Leber wird es zu 25-Hydroxyvitamin D (Calcifediol, dem Speicher- und Messwert im Blut) und in der Niere zu 1,25-Dihydroxyvitamin D (Calcitriol, der aktiven Form) umgewandelt. Calcitriol steigert über den Vitamin-D-Rezeptor die Aufnahme von Calcium und Phosphat im Darm, fördert die Mineralisierung des Knochens und bremst die Ausschüttung von Parathormon. Weil Vitamin D im Fettgewebe gespeichert wird, wirkt es lange nach und kann auch wöchentlich oder monatlich gegeben werden.","nebenwirkungen":{"gelegentlich":["Hyperkalzämie (erhöhtes Calcium im Blut)","Hyperkalziurie (erhöhtes Calcium im Urin)"],"selten":["Juckreiz, Hautausschlag, Nesselsucht"],"unbekannt":["Bei Überdosierung: Übelkeit, Erbrechen, Verstopfung, Appetitlosigkeit, starker Durst, vermehrtes Wasserlassen, Muskelschwäche, Verwirrtheit","Nierensteine und Verkalkungen in Niere und Gefässen bei langdauernder Überdosierung"]},"schwangerschaft":"In den empfohlenen Dosen erlaubt und bei Mangel sinnvoll; Überdosierungen vermeiden, da eine anhaltende Hyperkalzämie dem Kind schaden kann.","stillzeit":"In üblichen Dosen erlaubt; Vitamin D geht in die Muttermilch über, ersetzt aber nicht die Vitamin-D-Gabe an den Säugling.","hinweise":["Am besten zu einer Mahlzeit einnehmen, da fetthaltige Speisen die Aufnahme verbessern.","Hoch dosierte Wochen- oder Monatsdosen nicht mit täglichen Präparaten verwechseln und nicht mehrere Vitamin-D-Präparate kombinieren.","Bei hohen Dosen, Nierenkrankheit oder gleichzeitiger Calciumeinnahme Calcium im Blut kontrollieren lassen.","In der Schweiz wird für Säuglinge und Kleinkinder in den ersten 3 Lebensjahren eine tägliche Vitamin-D-Gabe empfohlen."],"darreichung":["Tropfen","Kapseln","Tabletten","Ampullen (hoch dosiert)"]},"cyanocobalamin":{"wirkmechanismus":"Ersetzt fehlendes Vitamin B12, das für die Blutbildung und die Nerven unentbehrlich ist. Cyanocobalamin wird im Körper in die aktiven Formen Methylcobalamin und Adenosylcobalamin umgewandelt. Diese sind Coenzyme der Methioninsynthase (Bildung von DNA-Bausteinen zusammen mit Folsäure, Abbau von Homocystein) und der Methylmalonyl-CoA-Mutase (wichtig für die Myelinscheiden der Nerven). Normalerweise wird B12 mit Hilfe des Intrinsic Factor im Dünndarm aufgenommen; aus hoch dosierten Tabletten gelangt rund 1 % auch ohne Intrinsic Factor ins Blut, weshalb sie auch bei perniziöser Anämie wirken können.","nebenwirkungen":{"sehrSelten":["Anaphylaktische Reaktionen (schwere allergische Reaktion, v. a. nach Injektion)"],"unbekannt":["Überempfindlichkeitsreaktionen der Haut (Juckreiz, Ausschlag, Nesselsucht)","Akne, akneähnlicher Ausschlag","Magen-Darm-Beschwerden wie Übelkeit oder Durchfall","Schmerzen und Rötung an der Injektionsstelle","Hypokaliämie (Kaliummangel) zu Beginn der Behandlung einer schweren Blutarmut"]},"schwangerschaft":"In üblichen Dosen zur Behandlung eines Mangels erlaubt; Vitamin B12 ist in der Schwangerschaft wichtig.","stillzeit":"Erlaubt; Vitamin B12 geht in die Muttermilch über, was bei Mangel der Mutter auch für das Kind wichtig ist.","hinweise":["Bei perniziöser Anämie oder nach Magenentfernung ist die Behandlung meist lebenslang nötig – nicht eigenmächtig absetzen.","Tabletten nüchtern mit Wasser einnehmen.","Zu Beginn der Behandlung Blutbild und Kalium kontrollieren lassen.","Bei Vitamin-B12-Mangel nie nur Folsäure einnehmen: die Blutarmut bessert sich, die Nervenschäden schreiten aber fort."],"darreichung":["Filmtabletten (hoch dosiert)","Injektionslösung"]},"cyproteron":{"wirkmechanismus":"Blockiert die Wirkung der männlichen Geschlechtshormone und drosselt zugleich deren Bildung. Cyproteronacetat verdrängt Testosteron und Dihydrotestosteron kompetitiv von den Androgenrezeptoren in den Zielorganen (Prostata, Haarfollikel, Talgdrüsen, Gehirn). Durch seine starke gestagene Wirkung hemmt es ausserdem über die Hirnanhangsdrüse die Ausschüttung von LH und FSH, wodurch der Testosteronspiegel sinkt. Bei Frauen hemmt es so auch den Eisprung.","nebenwirkungen":{"sehrHaeufig":["Verminderte Libido und Erektionsstörungen (Männer)","Reversible Hemmung der Samenbildung (Männer)"],"haeufig":["Leberschäden einschliesslich Gelbsucht, Hepatitis und Leberversagen","Gewichtszunahme oder -abnahme","Depressive Verstimmung, vorübergehende Unruhe","Müdigkeit, Hitzewallungen, Schwitzen","Atemnot (Dyspnoe)","Gynäkomastie (Brustvergrösserung beim Mann)"],"gelegentlich":["Hautausschlag"],"selten":["Überempfindlichkeitsreaktionen"],"sehrSelten":["Gutartige und bösartige Lebertumoren","Blutung in die Bauchhöhle (bei Lebertumoren)"],"unbekannt":["Meningeom (Hirnhauttumor), besonders bei langer Anwendung hoher Dosen","Thromboembolische Ereignisse (Thrombose, Embolie)","Anämie (Blutarmut) bei Langzeitbehandlung","Osteoporose","Bei Frauen: Zwischenblutungen, Brustspannen, Hemmung des Eisprungs"]},"schwangerschaft":"Kontraindiziert: Cyproteron kann bei männlichen Feten zu einer Verweiblichung führen. Frauen müssen während der Behandlung zuverlässig verhüten (in der Regel mit einer kombinierten Pille); eine Schwangerschaft vor Beginn ausschliessen.","stillzeit":"Kontraindiziert – etwa 0,2 % der Dosis gehen in die Muttermilch über und können beim Säugling antiandrogen wirken.","hinweise":["Leberwerte vor Behandlungsbeginn und regelmässig während der Therapie kontrollieren lassen; bei Gelbsucht, dunklem Urin oder Oberbauchschmerzen sofort ärztlichen Rat einholen.","Die niedrigste wirksame Dosis verwenden; bei Hautproblemen der Frau nach Besserung schrittweise reduzieren.","Müdigkeit und Konzentrationsschwäche können die Fahrtüchtigkeit beeinträchtigen; Alkohol schwächt die triebdämpfende Wirkung ab.","Neu auftretende Kopfschmerzen, Sehstörungen, Krampfanfälle oder Lähmungen ärztlich abklären lassen (Meningeom)."],"darreichung":["Tabletten"]},"cyproteron-ethinylestradiol":{"wirkmechanismus":"Dämpft die Wirkung männlicher Hormone auf Haut und Haarwurzeln und verhindert gleichzeitig den Eisprung. Cyproteronacetat blockiert die Androgenrezeptoren in Talgdrüsen und Haarfollikeln und vermindert über seine Gestagenwirkung die Androgenbildung in den Eierstöcken. Ethinylestradiol steigert in der Leber die Bildung des Bindungsproteins SHBG, wodurch weniger freies Testosteron im Blut zirkuliert, und stabilisiert den Zyklus. Zusammen hemmen beide den Eisprung.","nebenwirkungen":{"haeufig":["Übelkeit, Bauchschmerzen","Gewichtszunahme","Kopfschmerzen","Depressive Verstimmung, Stimmungsschwankungen","Brustschmerzen, Brustspannen"],"gelegentlich":["Erbrechen, Durchfall","Wassereinlagerungen","Migräne","Verminderte Libido","Brustvergrösserung","Hautausschlag, Nesselsucht"],"selten":["Venöse und arterielle Thromboembolien (Beinvenenthrombose, Lungenembolie, Herzinfarkt, Schlaganfall)","Unverträglichkeit von Kontaktlinsen","Überempfindlichkeitsreaktionen","Gewichtsabnahme, gesteigerte Libido","Ausfluss aus Scheide oder Brust","Erythema nodosum oder Erythema multiforme (entzündliche Hautrötungen)"],"unbekannt":["Blutdruckanstieg","Zwischen- und Schmierblutungen","Chloasma (bräunliche Pigmentflecken)","Meningeom (Hirnhauttumor)","Lebertumoren"]},"schwangerschaft":"Kontraindiziert. Vor Beginn eine Schwangerschaft ausschliessen; tritt eine Schwangerschaft ein, sofort absetzen.","stillzeit":"Kontraindiziert – die Wirkstoffe gehen in die Muttermilch über und können die Milchmenge vermindern.","hinweise":["21 Tage lang täglich zur gleichen Zeit eine Tablette, danach 7 Tage Pause; nach Abklingen der Haut- bzw. Haarbeschwerden (meist nach 3–4 Zyklen) die Notwendigkeit ärztlich überprüfen lassen.","Bei Erbrechen oder starkem Durchfall innerhalb von 3–4 Stunden nach der Einnahme ist der Verhütungsschutz unsicher.","Warnzeichen einer Thrombose (schmerzhaft geschwollenes Bein, plötzliche Atemnot, Brustschmerz, plötzliche Seh- oder Sprechstörung) sofort ärztlich abklären lassen.","Nicht rauchen; vor geplanten Operationen oder längerer Ruhigstellung die Einnahme ärztlich besprechen."],"darreichung":["Dragées (überzogene Tabletten)"]}});
